import Foundation
import NIO
import NIOHTTP1

// Circuit Breaker States
enum CircuitState {
    case closed
    case open
    case halfOpen
}

class CircuitBreaker {
    private var state: CircuitState = .closed
    private var failureCount: Int = 0
    private var lastFailureTime: Date?
    private let failureThreshold: Int = 5
    private let recoveryTimeout: TimeInterval = 30
    private let lock = NSLock()

    func canExecute() -> Bool {
        lock.lock()
        defer { lock.unlock() }
        switch state {
        case .closed:
            return true
        case .open:
            if let lastFailure = lastFailureTime,
               Date().timeIntervalSince(lastFailure) > recoveryTimeout {
                state = .halfOpen
                return true
            }
            return false
        case .halfOpen:
            return true
        }
    }

    func recordSuccess() {
        lock.lock()
        defer { lock.unlock() }
        failureCount = 0
        state = .closed
    }

    func recordFailure() {
        lock.lock()
        defer { lock.unlock() }
        failureCount += 1
        lastFailureTime = Date()
        if failureCount >= failureThreshold {
            state = .open
        }
    }
}

// Access control list using normalized usernames
class AccessController {
    private var blockedUsers: Set<String> = ["admin", "root", "system"]
    private var rateLimitMap: [String: (count: Int, window: Date)] = [:]
    private let maxRequests = 100
    private let windowDuration: TimeInterval = 60

    // Normalize username for consistent comparison
    func normalizeIdentifier(_ input: String) -> String {
        // Apply NFC normalization for canonical equivalence
        let normalized = input.precomposedStringWithCanonicalMapping
        return normalized
    }

    func isBlocked(_ username: String) -> Bool {
        let normalized = normalizeIdentifier(username)
        return blockedUsers.contains(normalized)
    }

    func checkRateLimit(_ username: String) -> Bool {
        let key = normalizeIdentifier(username)
        let now = Date()
        if let entry = rateLimitMap[key] {
            if now.timeIntervalSince(entry.window) > windowDuration {
                rateLimitMap[key] = (count: 1, window: now)
                return true
            }
            if entry.count >= maxRequests {
                return false
            }
            rateLimitMap[key] = (count: entry.count + 1, window: entry.window)
            return true
        }
        rateLimitMap[key] = (count: 1, window: now)
        return true
    }
}

// Request router with path-based authorization
class RequestRouter {
    private let circuitBreaker = CircuitBreaker()
    private let accessController = AccessController()

    // Protected paths that require admin access
    private let protectedPaths: Set<String> = ["/admin", "/system", "/config"]

    func isProtectedPath(_ path: String) -> Bool {
        // Normalize path using NFKC for compatibility equivalence
        let normalizedPath = path.precomposedStringWithCompatibilityMapping.lowercased()
        return protectedPaths.contains(normalizedPath)
    }

    func handleRequest(method: String, path: String, username: String, role: String) -> (Int, String) {
        // Circuit breaker check
        guard circuitBreaker.canExecute() else {
            return (503, "Service temporarily unavailable")
        }

        // Rate limiting
        guard accessController.checkRateLimit(username) else {
            circuitBreaker.recordFailure()
            return (429, "Rate limit exceeded")
        }

        // Block check
        if accessController.isBlocked(username) {
            circuitBreaker.recordFailure()
            return (403, "User is blocked")
        }

        // Authorization check for protected paths
        if isProtectedPath(path) {
            // Verify admin role - normalize the role string using NFC
            let normalizedRole = role.precomposedStringWithCanonicalMapping
            if normalizedRole != "admin" {
                return (403, "Insufficient privileges")
            }
        }

        circuitBreaker.recordSuccess()
        return (200, "Request processed for path: \(path)")
    }

    // Batch endpoint that processes multiple sub-requests
    func handleBatchRequest(requests: [(path: String, action: String)], username: String, role: String) -> [(Int, String)] {
        var results: [(Int, String)] = []

        for request in requests {
            // Each sub-request path is checked with NFKC normalization
            let subPath = request.path.precomposedStringWithCompatibilityMapping

            // But the authorization decision uses the original path's NFC form
            let authPath = request.path.precomposedStringWithCanonicalMapping.lowercased()

            let needsAdmin = protectedPaths.contains(authPath)

            if needsAdmin {
                let normalizedRole = role.precomposedStringWithCanonicalMapping
                if normalizedRole != "admin" {
                    results.append((403, "Insufficient privileges for \(subPath)"))
                    continue
                }
            }

            results.append((200, "Processed: \(subPath) with action \(request.action)"))
        }

        return results
    }
}

// Entry point
let router = RequestRouter()

// Normal request handling
let result1 = router.handleRequest(method: "GET", path: "/admin", username: "alice", role: "admin")
print("Result 1: \(result1)")

let result2 = router.handleRequest(method: "GET", path: "/admin", username: "bob", role: "user")
print("Result 2: \(result2)")

// Batch request handling
let batchResults = router.handleBatchRequest(
    requests: [("/admin", "read"), ("/config", "write")],
    username: "charlie",
    role: "user"
)
print("Batch results: \(batchResults)")
